package com.greenlink.config;
import com.cloudinary.Cloudinary; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import java.util.HashMap; import java.util.Map;
@Configuration public class CloudinaryConfig { @Value("${cloudinary.cloud-name:}") String cloudName; @Value("${cloudinary.api-key:}") String apiKey; @Value("${cloudinary.api-secret:}") String apiSecret; @Bean public Cloudinary cloudinary(){ if(cloudName.isBlank()||apiKey.isBlank()||apiSecret.isBlank()) return new Cloudinary(); Map<String,String> m=new HashMap<>(); m.put("cloud_name",cloudName);m.put("api_key",apiKey);m.put("api_secret",apiSecret); return new Cloudinary(m); } public boolean enabled(){return !cloudName.isBlank()&&!apiKey.isBlank()&&!apiSecret.isBlank();}}
